es"],"probin":null,"procost":100,"prokind":"f","proname":"dashboard_admin_live_member_daily","prorows":0,"pronargs":1,"proconfig":["search_path=\"\"","jit=off"],"proretset":false,"prosecdef":true,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_request"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"owner":"postgres","language":"plpgsql","replacements":[["private.dashboard_admin_yash_provider(y.supplier)","private.dashboard_admin_yash_order_provider(y.order_type,y.supplier,y.channel)"]]},{"signature":"private.dashboard_admin_live_provider_options(jsonb)","before":"5c3d9e9612ef7acd3e0adf4a65d8e16c","after":"8bc1df84f40062be7de68b87cda42b0a","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"dashboard_admin_live_provider_options","prorows":0,"pronargs":1,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":true,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_request"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":"({CONST :consttype 3802 :consttypmod -1 :constcollid 0 :constlen -1 :constbyval false :constisnull false :location -1 :constvalue 8 [ 32 0 0 0 0 0 0 32 ]})","pronargdefaults":1},"owner":"postgres","language":"plpgsql","replacements":[["    from yash_names\n    union\n","    from yash_names\n    union\n    -- The order supplier directory remains unchanged. Add the confirmed channel\n    -- identity from the small retained source channel catalog, never a second\n    -- historical orders scan or a per-order canonical lookup.\n    select private.dashboard_admin_live_provider_canonical(p.country,p.source_name,'UPI-QR')\n    from platforms p cross join lateral (\n      select true as matched from private.yash_channels c\n      where p.source='kb' and p.scope_group='IN' and p.source_name='YASH.BET'\n        and btrim(c.provider)='ArbPay'\n        and ((c.order_type='deposit' and btrim(c.channel_name)='Phonepe_QR')\n          or (c.order_type='withdrawal' and btrim(c.channel_name)='Arb-BANK'))\n        and c.order_type=any(case coalesce(p_request->>'direction','all') when 'all' then array['deposit','withdrawal'] when 'charge' then array['deposit'] else array['withdrawal'] end)\n      limit 1\n    ) channel_match\n    union\n"]]},{"signature":"private.dashboard_admin_live_submission_analysis(jsonb)","before":"08f4fda2ac67706ff667addfca4ffdf2","after":"bb4982e2601abd6928f8c441f1b8ccb6","metadata":{"proacl":["postgres=X/postgres","authenticated=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"dashboard_admin_live_submission_analysis","prorows":0,"pronargs":1,"proconfig":["search_path=\"\"","jit=off","enable_nestloop=off"],"proretset":false,"prosecdef":true,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_request"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"owner":"postgres","language":"plpgsql","replacements":[["private.dashboard_admin_yash_provider(y.supplier)","private.dashboard_admin_yash_order_provider(y.order_type,y.supplier,y.channel)"]]},{"signature":"private.dashboard_admin_yash_order_source()","before":"b0b42d95525b199b949561d8dbfed55f","after":"e017b0c815fd506bafb3bf4e54cf5bf0","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"dashboard_admin_yash_order_source","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":false,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"prop