proof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"owner":"postgres","language":"plpgsql","replacements":[["private.dashboard_admin_yash_provider(y.supplier)","private.dashboard_admin_yash_order_provider(y.order_type,y.supplier,y.channel)"]]},{"signature":"private.provider_snapshot_kernel_contract_current()","before":"ac21d75d1aaae2f396c670530821e494","after":"ca71c9502e56d6ed439f069a9bb0be1d","metadata":{"proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","proname":"provider_snapshot_kernel_contract_current","prorows":0,"pronargs":0,"proconfig":["search_path=\"\""],"proretset":false,"prosecdef":false,"prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"owner":"postgres","language":"sql","replacements":[["b07872f828acc18e8218ae6b2cc7d94e","3b2b0de6284bee1436f59c12fa5bcf66"],["08f4fda2ac67706ff667addfca4ffdf2","bb4982e2601abd6928f8c441f1b8ccb6"],["3d1188218a0aada52cfd2a5d6dbcbed6","776019c34ec5c4722d57ccf58615badb"]]}]$changes$::jsonb) loop
  if not exists(select 1 from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(spec->>'signature')
   and md5(p.prosrc)=spec->>'before' and pg_get_userbyid(p.proowner)=spec->>'owner' and l.lanname=spec->>'language'
   and (to_jsonb(p)-'oid'-'prosrc'-'prolang'-'proowner'-'pronamespace'-'prorettype')=spec->'metadata')
  then raise exception 'yash_shadow_definition_drift: %',spec->>'signature' using errcode='55000';end if;
 end loop;
 return (select md5(jsonb_build_object(
  'contract','provider-published-v1',
  'functions',(select jsonb_agg(jsonb_build_array(n.nspname,(case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end),pg_get_function_identity_arguments(p.oid),coalesce(($after${"private.dashboard_admin_live_expand_provider_filter(jsonb)":"3b2b0de6284bee1436f59c12fa5bcf66","private.dashboard_admin_live_member_daily(jsonb)":"e9aadf0d61a0ac40852277f4e8038830","private.dashboard_admin_live_provider_options(jsonb)":"8bc1df84f40062be7de68b87cda42b0a","private.dashboard_admin_live_submission_analysis(jsonb)":"bb4982e2601abd6928f8c441f1b8ccb6","private.dashboard_admin_yash_order_source()":"e017b0c815fd506bafb3bf4e54cf5bf0","private.dashboard_submission_streak_capture_day(jsonb,date,text[],text)":"fd1f61b5bf402ef3c61fabfc906ecae2","private.provider_snapshot_submission_kernel(jsonb,jsonb)":"776019c34ec5c4722d57ccf58615badb","private.provider_snapshot_kernel_contract_current()":"ca71c9502e56d6ed439f069a9bb0be1d"}$after$::jsonb)->>p.oid::regprocedure::text,md5(p.prosrc)),p.proconfig,p.prosecdef,p.provolatile,pg_get_userbyid(p.proowner),p.proacl::text,(select l.lanname from pg_language l where l.oid=p.prolang),p.proparallel,p.proisstrict,p.proleakproof,pg_get_function_arguments(p.oid),pg_get_function_result(p.oid),p.procost,p.prorows)order by n.nspname,(case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end),p.oid)
   from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and((case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end)=any(array[
    'dashboard_admin_live_query_raw','dashboard_admin_live_query','dashboard_admin_live_submission_analysis','dashboard_admin_live_intake_coverage',
    'dashboard_admin_live_remap_groups','dashboard_admin_live_expand_provider_filter','dashboard_admin_live_intake_order_feeds',
    'dashboard_admin_live_provider_canonical','dashboard_admin_wg_provider_aliases','dashboard_admin_live_provider_alias','dashboard_admin_live_provider_alias_values','dashboard_admin_live_confirmed_provider',
    'dashboard_data_group','dashboard_admin_fee_intervals','dashboard_admin_fee_category','dashboard_admin_ar_local_amount','provider_snapshot_dependency_token',
    'provider_snapshot_orders_raw_kernel','provider_snapshot_orders_result_kernel','provider_snapshot_submission_kernel',
    'provider_snapshot_order_feeds_kernel','provider_snapshot_intake_rows_kernel','provider_snapshot_compute_payload',
    'provider_snapshot_native_catalog','provider_snapshot_target_current','provider_snapshot_kernel_contract_current','dashboard_admin_live_platforms'])
    or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'dashboard_admin_yash_%'or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'ar_91club_submission_%'or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'ar_submission_fact_%'or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'maan_submission_%'
    or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'dashboard_admin_fee_%'or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'dashboard_admin_ar_%'or (case when p.oid=to_regprocedure('private.yash_channel_shadow_order_provider(text,text,text)') then 'dashboard_admin_yash_order_provider' else p.proname end) like 'dashboard_admin_order_business_%')),
  -- Fee outputs consume immutable versions, category presence and evidence eligibility,
  -- not the sheet publisher's observation/generation identity. Keep all IN directions.
  'feeSemantics',jsonb_build_object(
   'versions',(select coalesce(jsonb_agg(to_jsonb(v)order by v.id),'[]'::jsonb)
    from private.fee_rate_versions v where v.country='IN'),
   'openIntervalEvidence',(select coalesce(jsonb_agg(jsonb_build_array(v.id,
    exists(select 1 from private.fee_rate_current_evidence e
     join private.fee_rate_generations g on g.id=e.generation_id
     join public.third_party_rates r on r.id=e.source_id
     where e.rule_key=v.rule_key and e.version_id=v.id and e.state='ready'
      and r.updated_at=g.published_at))order by v.id),'[]'::jsonb)
    from private.fee_rate_versions v where v.country='IN'),
   'sourceCategories',(select coalesce(jsonb_agg(category order by category),'[]'::jsonb)
    from(select distinct upper(btrim(r.category)) category from public.third_party_rates r
     where private.dashboard_data_group(r.country,'')='IN') categories),
   'blockingEvidence',(select coalesce(jsonb_agg(jsonb_build_array(direction,category,provider)
    order by direction,category,provider),'[]'::jsonb)
    from(select distinct bad.direction,upper(btrim(r.category)) category,r.third_party provider
     from private.fee_rate_current_evidence bad
     join public.third_party_rates r on r.id=bad.source_id
     join private.fee_rate_generations generation on generation.id=bad.generation_id
     where (bad.version_id is null or bad.state<>'ready'
       or r.updated_at is distinct from generation.published_at)
      and private.dashboard_data_group(r.country,'')='IN') blockers)
  ),
  'registry',(select coalesce(jsonb_agg(jsonb_build_array(country,platform,raw_provider,canonical_values)order by country,platform,raw_provider),'[]'::jsonb)
    from private.dashboard_admin_provider_registry where country in('IN','印度')and platform in(p_target->>'name',p_target->>'source_name')),
  'overrides',(select coalesce(jsonb_agg(jsonb_build_array(country,platform,raw_provider,canonical_provider,version)order by country,platform,raw_provider),'[]'::jsonb)
    from private.dashboard_admin_provider_overrides where country in('IN','印度')and platform in(p_target->>'name',p_target->>'source_name')),
  'confirmations',(select coalesce(jsonb_agg(jsonb_build_array(order_kind,order_no,confirmed_provider)order by order_kind,order_no),'[]'::jsonb)
    from private.dashboard_admin_order_provider_confirmations where source_system='AR'and p_target->>'source'='ar'and country_code=p_target->>'scope_group'and platform=p_target->>'source_name'and active),
  'currencyProof',(select coalesce(jsonb_agg(jsonb_build_array(source_system,country_code,platform,currency)order by source_system,country_code,platform),'[]'::jsonb)
    from public.ar_config_targets where p_target->>'source'='ar'and source_system='AR'and country_code=p_target->>'scope_group'and platform=p_target->>'source_name')
 )::text));
end;$shadow_token$;
revoke all on function private.yash_channel_shadow_dependency_token(jsonb) from public,anon,authenticated,service_role;
commit;
